// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor funds the contract, and target is the adversarial recipient
    // The adversarial recipient will revert on receiving funds to simulate a failing low-level call.
    function testFuzz_property(address depositor, uint256 depositAmount, address target) public {
        // keep values in wide admissible domain
        vm.assume(depositAmount > 0 && depositAmount < type(uint128).max);
        // ensure depositor is a usable EOA
        vm.deal(depositor, depositAmount);

        // First, depositor calls fallback to deposit funds credited in balances[depositor]
        vm.prank(depositor);
        // call fallback by sending value to contract
        (bool okDeposit, ) = address(c).call{value: depositAmount}("\x00");
        // the deposit should succeed
        require(okDeposit);

        // Ensure target is a contract that will revert on receive to simulate failing low-level call.
        // If target is not a contract, deploy a Reverter and use its address instead to keep fuzz wide.
        address bad = target;
        // If target has no code, deploy a Reverter and use that to ensure the low-level call fails.
        if (target.code.length == 0) {
            Reverter r = new Reverter();
            bad = address(r);
        }

        // Now, artificially credit balances[bad] to simulate some pre-existing balance for bad
        // We cannot write to c.balances directly; simulate by having bad deposit into c.
        // Make an attacker EOA that will fund c and then we will set balances[bad] by depositing from bad address.
        // Deploy a helper that can force c to credit balances[bad] by sending value from bad.
        // Use vm.prank with bad to send value to c so fallback credits balances[bad].
        vm.deal(bad, 1 ether);
        vm.prank(bad);
        (bool okDeposit2, ) = address(c).call{value: 1 ether}("\x00");
        require(okDeposit2);

        // Sanity: balances[bad] should now be 1 ether
        uint256 before = c.balances(bad);
        require(before == 1 ether);

        // Now trigger withdraw as an arbitrary caller (depositor). The withdraw sends balances[msg.sender] to msg.sender.
        // We call withdraw from depositor so that c will attempt to send depositor's balance to depositor.
        // However the difference between reference and mutant is that when the low-level call fails, reference reverts
        // and mutant proceeds to zero balances regardless. To make the low-level call fail, we need msg.sender to be a contract that reverts on receive.
        // So perform withdraw from a reverter contract: deploy a Reverter and call withdraw from it via a wrapper.

        Reverter callerReverter = new Reverter();
        // Fund the reverter so it can be msg.sender for withdraw (not strictly necessary), but we need the call to fail when c sends funds to it.
        vm.deal(address(callerReverter), 0);

        // Credit balances of callerReverter so withdraw will attempt to send to it.
        // Have callerReverter send 0.1 ether to c to get credited
        vm.deal(address(callerReverter), 0.1 ether);
        // Use low-level call from the reverter contract to c's fallback to credit balances[callerReverter]
        // We need to execute a call as the reverter contract: create a helper that has a function to forward calls; but minimal approach: call a deployer that uses the reverter to send value—since we already have the contract, we can use address(callerReverter).call{value: amount} to invoke receive on reverter, but we need the reverter to send value to c. Simpler: have depositor credit balances[callerReverter] by having depositor call c and then manually set balances via the reverter? That is not possible.
        // Simpler plan: Use depositor (an EOA) to call withdraw; when c sends funds to depositor it will succeed (EOA). That won't cause failing send. To trigger a failing send on c's attempt, we must call withdraw with msg.sender being a contract that reverts on receive. We therefore need to have that contract possess a non-zero balance in c.balances.
        // Achieve that by having the reverter contract perform a deposit to c itself. Call into c from the reverter to credit its balances via its fallback. We'll invoke a helper DeferSender that can call c on behalf of reverter. Instead, we can make the Reverter contract include a function to deposit into c. We have a minimal Reverter below that has deposit function.

        // Use Reverter's deposit ability
        callerReverter.deposit{value: 0.1 ether}(address(c));
        // Confirm balances of callerReverter is 0.1 ether
        uint256 reverterBal = c.balances(address(callerReverter));
        require(reverterBal == 0.1 ether);

        // Now call withdraw from the reverter so that c will attempt to send 0.1 ether to the reverter and that send will fail (reverter reverts on receive)
        bool withdrawOk;
        try callerReverter.doWithdraw(address(c)) {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }

        // The general rule: for the reference contract, if the send to msg.sender fails, withdraw reverts and state is unchanged; for the mutant that ignores the send result, balances[k] can be zeroed even when the send failed.
        // We assert a universal property that still holds for the reference: after the failed send (withdraw reverted), balances[bad] remains 1 ether.
        // Because reference reverts on failing send, the earlier balances[bad] (1 ether) must be preserved for all inputs. The mutant that zeros balances regardless will cause this assertion to fail for some inputs (when a failing send occurs).

        // Single required assertion reading c's public surface:
        assertTrue(c.balances(bad) == 1 ether);
    }
}

// Minimal adversarial helper that reverts on receive and can deposit/doWithdraw
contract Reverter {
    // deposit into target contract to credit this contract's balances
    function deposit(address payable target) external payable {
        (bool ok, ) = target.call{value: msg.value}("");
        require(ok);
    }
    receive() external payable {
        revert("boom");
    }
    // call withdraw() on target
    function doWithdraw(address target) external {
        C(target).withdraw();
    }
}

