pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: amount to deposit and the adversarial recipient address (as bool choose deployer or fuzzed)
    // We must fuzz at least one parameter; we fuzz the deposit amount and an address which we interpret as whether
    // to use the adversarial Reverter contract or a normal EOA. The fuzzer will explore amounts and the flag.
    function testFuzz_property(uint256 depositAmount, address maybeReverter) public {
        // Keep depositAmount within reasonable bounds and non-zero to exercise behavior
        depositAmount = bound(depositAmount, 1 wei, 1 ether);

        // Deploy a reverter helper that will always revert on receive/call
        Reverter rev = new Reverter();

        // Choose target: use the reverter contract if the provided address's low bit is 1, else use an EOA
        bool useReverter = (uint160(maybeReverter) & 1) == 1;
        address target = useReverter ? address(rev) : address(uint160(maybeReverter));

        // Fund an actor who will deposit into C (EOA)
        address depositor = vm.addr(1);
        vm.deal(depositor, depositAmount);

        // depositor deposits into C via fallback (payable) so balances[depositor] increases by depositAmount
        vm.prank(depositor);
        (bool okDeposit, ) = address(c).call{value: depositAmount}("");
        require(okDeposit, "deposit failed in setup");

        // Also set balances[target] to depositAmount by having target deposit to C (either EOA or the reverter cannot receive funds,
        // but for mapping balances it matters who msg.sender is during fallback; we need target's address as msg.sender when sending Ether to C
        // If target is the Reverter, it can call C only from its fallback which reverts; so instead we emulate target being able to fund balances by using a proxy.
        // We'll deploy a Sender helper that can send to C with msg.sender preserved (by having Sender contract funded and calling C),
        // and we choose to instruct Sender to act as target via its own address being the mapping key.

        Sender sender = new Sender();
        vm.deal(address(sender), depositAmount);
        // Have sender send depositAmount to C so balances[address(sender)] = depositAmount
        sender.sendDeposit{value: depositAmount}(address(c));

        // Now ensure balances[address(sender)] == depositAmount in the reference contract
        assertTrue(c.balances(address(sender)) == depositAmount, "sanity: sender balance not set");

        // Now attempt withdraw called by sender (so msg.sender == address(sender)) which causes C to call sender
        // If sender is a normal contract that accepts funds, reference's send succeeds and balances zeroed; if send fails (e.g., target reverts), reference reverts.
        // To route the external interaction through an adversarial failing callee, we will have the Sender attempt to withdraw but the recipient of the low-level call
        // inside C is msg.sender (which will be address(sender)). To simulate a failing recipient for C's call we deploy a BreakingReceiver and make sender delegatecall it
        // However, simpler: make a special Sender that, when withdraw causes C to call back to Sender, the Sender's fallback reverts to simulate a failing external party.

        // We will toggle Sender's behavior: either its fallback accepts funds or reverts. Set it to revert if useReverter==true
        sender.setShouldRevert(useReverter);

        // Now perform the withdraw: call c.withdraw() with msg.sender == address(sender)
        vm.prank(address(sender));
        bool ok;
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: In the correct contract, when the low-level send to msg.sender fails, the withdraw call reverts (so ok==false). When the low-level send would succeed, withdraw returns (ok==true).
        // This universal property distinguishes the reference from the mutant: the mutant can return ok==true even when the external send to msg.sender fails, because it ignores the send result and proceeds to zero balances.
        // We assert that ok equals the success of sending value to address(sender) from the context of C. We can determine that by attempting a direct low-level call from this test to address(sender)
        // sending depositAmount: if such a call would revert, then C's low-level call would also revert, and reference must have ok==false. If such a call succeeds, reference must have ok==true.

        // Perform a direct test call to sender to see whether it accepts plain transfers (this models whether C's low-level call to sender would succeed).
        (bool directAccept, ) = address(sender).call{value: depositAmount}("");

        // The property: ok (result of c.withdraw) must equal directAccept
        assertTrue(ok == directAccept);
    }
}

// Helper contract that can accept or revert on fallback/receive, and can send a deposit to C
contract Sender {
    bool public shouldRevert;

    function setShouldRevert(bool v) external {
        shouldRevert = v;
    }

    // allow funding
    receive() external payable {
        if (shouldRevert) revert("reject");
    }
    fallback() external payable {
        if (shouldRevert) revert("reject");
    }

    // send deposit to C so that balances[this] increases
    function sendDeposit(address caddr) external payable {
        // forward Ether to C via plain call so msg.sender == address(this)
        (bool ok, ) = caddr.call{value: msg.value}("");
        require(ok, "deposit to C failed");
    }
}

// Minimal reverter helper (not used directly but available)
contract Reverter {
    fallback() external payable { revert("revert"); }
}

