pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor funds amount and target address index (we will use two addresses)
    function testFuzz_property(uint256 depositAmount, address target) public {
        // keep depositAmount in a reasonable range but wide
        depositAmount = bound(depositAmount, 1, 1 ether);
        // prepare two actors: depositor and the adversarial target (which may be a contract)
        address depositor = address(0xABCD);

        // Deploy a reverting helper and treat its address as the target when fuzzed target is a contract
        Reverter rev = new Reverter();
        address maybeReverter = target == address(0) ? address(rev) : (isContract(target) ? target : address(rev));

        // Fund depositor and the contract c so it can process balances via fallback
        vm.deal(depositor, depositAmount);
        // depositor sends Ether to C via fallback to increase balances[depositor]
        vm.prank(depositor);
        (bool okDeposit, ) = address(c).call{value: depositAmount}("0x");
        require(okDeposit);

        // Also set balances[maybeReverter] by impersonating it and sending value to C fallback
        vm.deal(maybeReverter, depositAmount);
        vm.prank(maybeReverter);
        (bool okDeposit2, ) = address(c).call{value: depositAmount}("0x");
        require(okDeposit2);

        // Sanity: record balance mapping for the target before withdraw
        uint256 before = c.balances(maybeReverter);
        // make sure we actually set a positive balance for the target
        vm.assume(before > 0);

        // Now invoke withdraw as the target; if the target is the Reverter contract, its fallback/receive will revert
        vm.prank(maybeReverter);
        bool withdrawSucceeded;
        try c.withdraw() {
            withdrawSucceeded = true;
        } catch {
            withdrawSucceeded = false;
        }

        // The general property: on the correct contract, if the low-level send to maybeReverter fails, the whole call reverts
        // and therefore balances(maybeReverter) remains unchanged (equal to before). We assert that balances did NOT become zero
        // unconditionally here: reference preserves balances when send fails; the mutant that ignores the send result can zero it.
        // We assert reading c's public getter once.
        assertTrue(c.balances(maybeReverter) == before);
    }

    // helper to detect if an address is a contract in the test environment
    function isContract(address addr) internal view returns (bool) {
        uint256 size;
        assembly { size := extcodesize(addr) }
        return size > 0;
    }
}

// adversarial helper: always revert on receive/fallback to simulate a failing callee
contract Reverter {
    fallback() external payable { revert("fail"); }
    receive() external payable { revert("fail"); }
}

