import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: depositor funds the contract, attacker is a deployed contract that will reenter,
    // attackerDeposit is how much attacker initially funded, victimDeposit is how much victim funded.
    function testFuzz_property(address depositor, uint256 victimDeposit, uint256 attackerDeposit) public {
        // keep addresses sensible
        vm.assume(depositor != address(0));
        // bound deposits to reasonable amounts so vm.deal works
        victimDeposit = bound(victimDeposit, 1, 1 ether);
        attackerDeposit = bound(attackerDeposit, 1, 1 ether);
        // deploy attacker contract which will attempt reentrancy on withdraw
        Attacker attacker = new Attacker(c);

        // fund depositor (victim) and attacker externally
        vm.deal(depositor, victimDeposit);
        vm.deal(address(attacker), attackerDeposit);

        // victim deposits
        vm.prank(depositor);
        (bool sentVictim, ) = address(c).call{value: victimDeposit}(
            abi.encodeWithSignature("")
        );
        require(sentVictim);

        // attacker deposits
        vm.prank(address(attacker));
        (bool sentAtt, ) = address(c).call{value: attackerDeposit}(
            abi.encodeWithSignature("")
        );
        require(sentAtt);

        // snapshot victim balance stored in contract before withdrawal
        uint256 beforeVictim = c.balances(depositor);

        // attacker will initiate withdraw from its own address which during receive will reenter
        // into c.withdraw() targeting depositor (attempting to drain or modify depositor's balance)
        // start the prank so calls originate from attacker contract address
        vm.prank(address(attacker));
        attacker.attack(depositor);

        // After the withdrawal sequence completes, the reference contract with the lock guarantees
        // that victim's recorded balance inside c is unchanged by other addresses' reentrant behavior.
        // The mutant removing the lock allows reentrant modification; thus the universal property is:
        // c.balances(depositor) == beforeVictim for all inputs on the correct contract.
        assertTrue(c.balances(depositor) == beforeVictim);
    }
}

