pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters:
    // - attackerInitial: amount the attacker funds the contract with (and will later withdraw)
    // - victimInitial: amount a victim funds the contract with (whose balance should remain unchanged by someone else's withdraw)
    // - attackerIsCaller: which address will act as the caller/attacker (0 -> use attacker contract, 1 -> use EOA)
    function testFuzz_property(uint256 attackerInitial, uint256 victimInitial, uint8 attackerIsCaller) public {
        // Keep amounts in a reasonable wide domain but non-zero to allow meaningful behavior
        attackerInitial = bound(attackerInitial, 1, 1 ether);
        victimInitial = bound(victimInitial, 1, 1 ether);

        // Deploy adversarial reentrant helper that will call back into c during receive()
        Attacker attacker = new Attacker(c);

        // Two participants: attacker.address and victim (EOA)
        address victim = address(0xBEEF);

        // Fund attacker and victim EOAs so they can send value
        vm.deal(address(attacker), attackerInitial);
        vm.deal(victim, victimInitial);

        // Victim funds the contract via fallback (external payable)
        vm.prank(victim);
        (bool okV, ) = address(c).call{value: victimInitial}("");
        require(okV);

        // Attacker funds the contract via the attacker contract's helper function which forwards value
        // Use the attacker contract so it has executable code (necessary for reentrancy)
        attacker.fund{value: attackerInitial}();

        // Record victim balance in contract before withdraw
        uint256 victimBalanceBefore = c.balances(victim);

        // Now trigger withdraw from attacker; attacker.reenter will try to reenter and during reentrancy attempt to manipulate victim's balance
        // Choose whether the attacker contract itself calls withdraw (attackerIsCaller==0) or an EOA calls withdraw (attackerIsCaller!=0)
        if (attackerIsCaller == 0) {
            // attacker contract calls withdraw and will reenter via its receive()
            attacker.doWithdraw();
        } else {
            // EOA calls withdraw directly (no reentrancy possible because EOAs have no code)
            vm.prank(address(attacker));
            try c.withdraw() {
                // no-op
            } catch {
                // no-op
            }
        }

        // Exactly one assertion: in the correct contract, victim's stored balance must remain the same after attacker withdraw
        uint256 victimBalanceAfter = c.balances(victim);
        assertTrue(victimBalanceAfter == victimBalanceBefore);
    }
}

