pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: attacker initial funding, victim initial funding, victim address selector (as uint8 to index attacker/victim roles)
    function testFuzz_property(uint256 attackerFund, uint256 victimFund, uint8 victimSelector) public {
        // keep funds in reasonable bounds but wide
        attackerFund = bound(attackerFund, 0, 1 ether);
        victimFund = bound(victimFund, 0, 1 ether);

        // Setup two addresses: addr1 and addr2
        address addr1 = address(0xA1);
        address addr2 = address(0xB2);
        // choose victim as one of them based on fuzzed selector
        address victim = (victimSelector % 2 == 0) ? addr1 : addr2;
        address attacker = (victim == addr1) ? addr2 : addr1;

        // Deploy an attacker helper that will reenter into c.withdraw when it receives ETH
        AttackerHelper atk = new AttackerHelper(address(c), attacker);

        // Fund attacker helper and victim externally so they can call fallback to deposit
        vm.deal(attacker, attackerFund);
        vm.deal(victim, victimFund);

        // Victim deposits funds by calling fallback (external payable). Use prank to send from victim
        if (victimFund > 0) {
            vm.prank(victim);
            (bool okV, ) = address(c).call{value: victimFund}("");
            require(okV);
        }

        // Attacker deposits funds by calling fallback from attacker; deposit into helper so the helper holds the attacker identity
        if (attackerFund > 0) {
            vm.prank(attacker);
            (bool okA, ) = address(c).call{value: attackerFund}("");
            require(okA);
        }

        // Record victim balance in contract before attacker's withdraw
        uint256 beforeVictimBalance = c.balances(victim);

        // Make the attacker be the msg.sender for withdraw; when attacker calls withdraw, the helper will attempt reentrancy
        // We need the call to originate from the helper's address, so we deploy helper and have it call c.withdraw in its attack function
        // Give helper some gas by ensuring it has a small balance (not strictly necessary but safe)
        vm.deal(address(atk), 1 wei);

        // Trigger attack: attacker instructs helper to run the attack; pass attacker as the caller by using vm.prank
        vm.prank(attacker);
        atk.attack(); // helper will call c.withdraw() and during receive will try to reenter and call c.withdraw() again

        // After attack completes, check victim's stored balance in c
        uint256 afterVictimBalance = c.balances(victim);

        // General property: victim's stored balance should not decrease after someone else's withdraw in the reference contract
        // (assert that reference maintains balances[victim] >= before). This should hold for reference C for all inputs,
        // but the mutant that removes the lock can make afterVictimBalance < beforeVictimBalance for some inputs.
        assertTrue(afterVictimBalance >= beforeVictimBalance);
    }
}

// Minimal attacker helper that will reenter during receive
contract AttackerHelper {
    C parent;
    address attackerEOA;
    bool reentered;

    constructor(address _parent, address _attackerEOA) {
        parent = C(_parent);
        attackerEOA = _attackerEOA;
        reentered = false;
    }

    // Called by the test (with msg.sender set to attacker EOA). This function calls parent.withdraw()
    function attack() external {
        // call withdraw as this helper contract
        parent.withdraw();
    }

    // When receiving ETH from parent.withdraw, attempt reentrancy once: call withdraw again targeting the parent
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // call withdraw reentrantly
            parent.withdraw();
        }
        // otherwise do nothing
    }
}

