contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed params:
    // - depositAmt: amount the victim deposits (and which attacker may try to affect)
    // - attackerDeposit: amount the attacker deposits to have a non-zero balance
    // - victim: an address that will deposit and may be targeted
    function testFuzz_property(uint256 depositAmt, uint256 attackerDeposit, address victim) public {
        // keep values in reasonable gas/uint ranges but wide enough
        depositAmt = bound(depositAmt, 1, 1 ether);
        attackerDeposit = bound(attackerDeposit, 1, 1 ether);
        vm.assume(victim != address(0));

        // Deploy a reentrant attacker helper that will call back into c during its receive
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // Fund victim and attacker
        vm.deal(victim, depositAmt);
        vm.deal(address(attacker), attackerDeposit + 1 wei);

        // victim deposits into c
        vm.prank(victim);
        (bool okVictim, ) = address(c).call{value: depositAmt}(
            abi.encodeWithSelector(bytes4(0)) // triggers fallback payable
        );
        require(okVictim);

        // attacker deposits into c so it has a balance to call withdraw
        vm.prank(address(attacker));
        (bool okAttDep, ) = address(c).call{value: attackerDeposit}(
            abi.encodeWithSelector(bytes4(0))
        );
        require(okAttDep);

        // Record victim balance before attacker withdraws
        uint256 before = c.balances(victim);

        // Now attacker will call withdraw. During withdraw, its fallback/receive will reenter
        // and attempt to call c.withdraw again and manipulate balances if allowed by mutant.
        // Use try/catch to ensure we proceed regardless of revert behavior.
        try attacker.attack() {
            // attack attempted
        } catch {
            // ignore failures; property must hold for all inputs on correct contract
        }

        // Single assertion: after attacker withdraw attempt, victim's stored balance must equal before
        // This is true for the reference C (reentrancy lock prevents modifying other balances),
        // but the mutant removing the lock can change victim's balances via reentrancy.
        assertTrue(c.balances(victim) == before);
    }
}

// Minimal reentrant attacker: on receive, it tries to call withdraw again into C
contract ReentrantAttacker {
    C immutable target;
    bool reentered;
    constructor(C _target) {
        target = _target;
    }

    // deposit when attack is invoked
    function attack() external payable {
        // call withdraw from this contract (has a balance if set up by test)
        // wrap in try to avoid bubbling reverts to test harness
        try target.withdraw() {
        } catch {
        }
    }

    // receive will attempt to reenter withdraw once
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // Attempt to reenter withdraw
            try target.withdraw() {
            } catch {
            }
        }
    }
}

