contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz params: attacker deposit, victim deposit, attacker address (used to deploy an attacker helper via prank)
    // We keep domains wide but ensure non-zero deposits so withdraw does something.
    function testFuzz_property(uint256 attackerDeposit, uint256 victimDeposit, address attackerEOA) public {
        // keep deposits in reasonable bounded range for test environment
        attackerDeposit = bound(attackerDeposit, 1, 1 ether);
        victimDeposit = bound(victimDeposit, 1, 1 ether);
        // attackerEOA must be non-zero and distinct from this contract
        vm.assume(attackerEOA != address(0));
        vm.assume(attackerEOA != address(this));

        // Set up victim: fund from a designated address
        address victim = address(0xBEEF);
        vm.deal(victim, victimDeposit);
        vm.prank(victim);
        // victim deposits into c via fallback payable
        (bool sentV, ) = address(c).call{value: victimDeposit}('');
        require(sentV);

        // Deploy an attacker helper contract from attackerEOA; it will reenter c.withdraw when receiving funds
        vm.deal(attackerEOA, attackerDeposit);
        vm.startPrank(attackerEOA);
        Attacker attacker = new Attacker(address(c));
        // Attacker funds c (this goes to balances[attackerEOA])
        (bool sentA, ) = address(c).call{value: attackerDeposit}('');
        require(sentA);
        vm.stopPrank();

        // Record pre-withdraw total contract balance and attacker's stored balance
        uint256 preContractBal = address(c).balance;
        uint256 attackerStoredBefore = c.balances(address(attacker));

        // Now have the attacker call withdraw via its helper, which will trigger a reentrant attempt
        // Use try/catch to capture success/failure but we only assert on the contract balance relation below
        bool ok;
        try attacker.callWithdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: in the correct contract (with reentrancy lock), the contract balance must drop by exactly attacker's stored balance
        // i.e., address(c).balance == preContractBal - attackerStoredBefore
        // This reads only c's public surface (address(c).balance) and the public getter balances
        assertTrue(address(c).balance == preContractBal - attackerStoredBefore);
    }
}

// Minimal attacker helper: on receive, attempt to reenter withdraw once
contract Attacker {
    C public target;
    bool public reentered;
    constructor(address _t) {
        target = C(_t);
        reentered = false;
    }
    receive() external payable {
        // attempt a single reentrant call to withdraw; mutant without lock may allow this to alter other balances
        if (!reentered) {
            reentered = true;
            // ignore revert to allow withdraw to continue
            try target.withdraw() {
            } catch {
            }
        }
    }
    function callWithdraw() external {
        // call withdraw as the attacker (msg.sender will be this contract)
        target.withdraw();
    }
}

