pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep amount in a sensible range (not too huge) but very wide
        amount = bound(amount, 0, 1 ether);
        // avoid the zero address for the depositor (not necessary but keeps semantics clear)
        vm.assume(depositor != address(0));

        // deploy an adversarial helper that will revert or consume lots of gas in its fallback
        MaliciousReceiver mal = new MaliciousReceiver();

        // fund the depositor so they can send value
        vm.deal(depositor, amount);

        // Have the malicious receiver act as the depositor (so msg.sender in fallback is the malicious contract)
        // We need to have the malicious contract call the vulnerable contract's fallback to deposit funds
        // to ensure balances[mal] > 0. Use vm.prank to make the deposit originate from depositor first to mal,
        // then have mal forward the deposit to c so msg.sender in c.fallback will be mal.

        if (amount > 0) {
            // deposit ETH into mal so it can forward to c
            vm.prank(depositor);
            (bool s,) = payable(address(mal)).call{value: amount}("deposit");
            require(s);

            // have mal forward its balance to c by calling c's fallback (this makes balances[mal] increase)
            mal.forwardToC{value: amount}(address(c));
        }

        // Now mal is the recorded depositor in c.balances[mal]
        // Call withdraw as mal and observe whether it completes.
        bool ok;
        try this.callWithdrawAs(address(mal)) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (one assert): on the reference implementation, withdraw always completes successfully for any depositor and amount.
        // The mutant using transfer can revert for some malicious receivers; the fuzzer should find such inputs.
        assertTrue(ok);
    }

    // helper that calls c.withdraw() as the given caller (must be external so try/catch above can catch reverts)
    function callWithdrawAs(address who) external {
        // prank as who and call withdraw
        vm.prank(who);
        c.withdraw();
    }
}

// Malicious receiver that consumes more than 2300 gas in its fallback so transfer would revert
contract MaliciousReceiver {
    // accept deposits
    receive() external payable {}

    // forward to C by calling its fallback (so msg.sender inside C is this contract)
    function forwardToC(address payable c) external payable {
        // call C fallback sending ETH
        (bool s, ) = c.call{value: msg.value}("");
        require(s);
    }

    // When C attempts to transfer to this contract, consume lots of gas to cause transfer to revert
    fallback() external payable {
        // do expensive work to consume >2300 gas
        // loop that touches storage to burn gas
        for (uint i = 0; i < 100; i++) {
            // arbitrary storage write
            bytes32 slot = keccak256(abi.encodePacked(i));
            assembly {
                sstore(slot, 0x123)
            }
        }
    }
}

