    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep amount bounded to avoid overflow issues when dealing with test harness
        amount = bound(amount, 0, 1 ether);
        // ensure depositor is not the zero address to allow payable interactions
        vm.assume(depositor != address(0));

        // deploy an adversarial recipient that consumes >2300 gas in fallback
