        // fund the depositor so they can send value
        vm.deal(depositor, amount);

        // Have depositor send 'amount' ETH to c via fallback, but route origin as malicious
        // We want the eventual withdraw to send funds to malicious, so we must make balances[malicious] > 0.
        // To do that, have malicious call c with value as depositor would: impersonate malicious to send value
        vm.prank(depositor);
        // send value from depositor to c; this will credit balances[msg.sender] where msg.sender == depositor
        (bool sent,) = address(c).call{value: amount}("");
        // If no funds were sent (amount==0), the property is trivial; still proceed.

        // Now transfer the recorded balance to the malicious contract by making a direct internal move:
        // We cannot mutate c.balances directly; instead, have depositor withdraw to themselves and then forward to malicious.
        // But withdraw sends to msg.sender; to trigger withdraw sending to malicious, we need msg.sender == malicious.
        // So instead, perform the deposit as malicious in the first place.
        // Re-deploy scenario: do deposit from malicious directly so c.balances[malicious]==amount.

        // Reset state by redeploying C to ensure balances are from malicious
        c = new C();
        vm.deal(depositor, amount);
        // have malicious deposit amount by impersonating malicious as sender but funding from depositor is unnecessary; vm.prank sets msg.sender only
        vm.prank(address(malicious));
        // ensure malicious has ETH to send
        vm.deal(address(malicious), amount);
        (bool okDeposit,) = address(c).call{value: amount}("");
        // Now malicious has a recorded balance in c

        // Now call withdraw as malicious (so c will send to malicious fallback)
